//! THE TREE'S TOOLCHAIN: `trust.lock` (docs/DESIGN-fast-build-release-2026-11-05.md §4.7, A14).
//!
//! A checkout names the Trust build it compiles with, by number and by content, in a generated
//! `trust.lock` at its root, so the compiler moves only by a commit and an index that publishes a
//! newer build changes no build of a locked tree. `atpkg-publish adopt trust=<build>` writes it
//! (with a seal line, `aterm_census::seal`); nothing else does.
//!
//! ```toml
//! # @generated by … (seal …); rerun it, never edit by hand.
//! version = 1
//!
//! [trust]
//! build = 16387
//! tree_root = "<64 hex: the signed tree root of the build's pack>"
//! compiler_commit = "<40 hex: `trustc -vV`'s commit-hash>"
//! receipt = "<what proves the build's lineage, e.g. SEED-MINT sha256:<64 hex>>"
//!
//! [stock]
//! toolchain = "<the exact upstream release the STOCK EXCEPTION slices build with>"
//! ```
//!
//! A reader finds the lock by walking up from the directory a build runs in ([`find`]), as rustup
//! finds `rust-toolchain.toml`, and resolves the locked build in the atpkg store
//! ([`locked_build`]): `<prefix>/store/trust/<build>` whose recorded tree root
//! ([`TREE_ROOT_SUFFIX`]) is the lock's. A lock that cannot be read or parsed is an error, never
//! the absence of a lock: a tree that names its compiler never falls back to whichever build is
//! current.

use std::path::{Path, PathBuf};

use crate::discovery::{MAX_ATERM_CONFIG_BYTES, is_executable_file, tool_file};

/// The lock's file name, at a checkout's root.
pub const LOCK_FILE: &str = "trust.lock";

/// The one format version this reader knows; a lock that says another is refused.
pub const LOCK_VERSION: u64 = 1;

/// The suffix of the record beside a store build that holds the signed tree root its stage
/// verified, or a fold of the tree found there ([`tree_root_record_text`]):
/// `<prefix>/store/<program>/<build>.tree_root`.
pub const TREE_ROOT_SUFFIX: &str = ".tree_root";

/// The record's first line.
const TREE_ROOT_HEADER: &str = "tree_root v1";

/// The suffix of the mark beside a store build explicitly installed or resolved by a tree's
/// lock: its modification time is the last use ([`mark_used`]), and gc keeps a build marked within
/// [`LOCKED_KEEP`], current or not.
pub const LOCKED_SUFFIX: &str = ".locked";

/// How long after explicit installation or lock resolution gc keeps a build ([`LOCKED_SUFFIX`]).
pub const LOCKED_KEEP: std::time::Duration = std::time::Duration::from_secs(14 * 24 * 3600);

/// How stale a mark may be before a resolution rewrites it: one write an hour, not one per build.
const MARK_FRESH: std::time::Duration = std::time::Duration::from_secs(3600);

/// The store program a lock names builds of.
pub const PROGRAM: &str = "trust";

/// What puts Trust on a machine no published build serves, wherever the store's own readers say
/// it (the shim hop, a pending stub, `which`, a rerouted tool): a local build of its own linked
/// into the store, whose shims then run it, and which takes a lock's place as a dev link does in
/// discovery.
pub const LOCAL_SYSROOT_REMEDY: &str = "a locally built Trust sysroot links in with `aterm pkg \
     link trust <sysroot> bin/trustc bin/targo …` (docs/LINUX-LOCAL-TOOLCHAIN.md)";

/// [`LOCAL_SYSROOT_REMEDY`] where the reader takes `$TRUST_STAGE2_BIN`'s toolchain ahead of the
/// store's (toolchain discovery, and an explicit lane's `targo`): there naming the local build's
/// bin in that variable puts it in place too. A reader that never reads the variable says
/// [`LOCAL_SYSROOT_REMEDY`].
pub const LOCAL_SYSROOT_OR_STAGE2_REMEDY: &str = "a locally built Trust sysroot links in with \
     `aterm pkg link trust <sysroot> bin/trustc bin/targo …`, or TRUST_STAGE2_BIN names its bin \
     (docs/LINUX-LOCAL-TOOLCHAIN.md)";

/// What a `trust.lock` says.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct TrustLock {
    /// The Trust store build number (`store/trust/<build>`).
    pub build: u64,
    /// The signed tree root of that build's pack, 64 lowercase hex digits.
    pub tree_root: String,
    /// The commit its `trustc -vV` answers as `commit-hash`, 40 lowercase hex digits.
    pub compiler_commit: String,
    /// What proves the build's lineage (its mint receipt's digest).
    pub receipt: String,
    /// The exact upstream toolchain the STOCK EXCEPTION slices build with.
    pub stock_toolchain: String,
}

/// A lock found on the walk up from a directory ([`find`]).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Found {
    /// The lock file.
    pub path: PathBuf,
    /// What it says, or why it could not be read: a reader refuses rather than fall back.
    pub lock: Result<TrustLock, String>,
    /// Why no published install of the lock's build can satisfy it on this machine's target, when
    /// the store's signed manifests say so (atpkg's `trust_lock::found_for`): that build has no
    /// pack for the target, or one with another tree. `None` from [`find`], which reads only the
    /// file.
    pub unpublished: Option<String>,
}

impl Found {
    /// The checkout the lock belongs to: the directory holding it.
    #[must_use]
    pub fn root(&self) -> &Path {
        self.path.parent().unwrap_or(Path::new("/"))
    }
}

/// The first `trust.lock` at or above `start`, read and parsed, or `None` when no directory on
/// the way up holds one. `start` is taken as given (a relative one is read against the process's
/// directory). Anything at that name that is not a readable regular file of at most
/// [`MAX_ATERM_CONFIG_BYTES`] is a found lock that does not parse.
#[must_use]
pub fn find(start: &Path) -> Option<Found> {
    let mut dir = Some(start);
    while let Some(here) = dir {
        let path = here.join(LOCK_FILE);
        if std::fs::symlink_metadata(&path).is_ok() {
            let lock = read(&path);
            return Some(Found {
                path,
                lock,
                unpublished: None,
            });
        }
        dir = here.parent();
    }
    None
}

/// The lock at `path`, parsed.
///
/// # Errors
/// When it is not a readable UTF-8 regular file within [`MAX_ATERM_CONFIG_BYTES`], or does not
/// parse ([`parse`]).
pub fn read(path: &Path) -> Result<TrustLock, String> {
    let text =
        crate::discovery::read_bounded_text(path, MAX_ATERM_CONFIG_BYTES).ok_or_else(|| {
            format!(
                "{} is not a readable UTF-8 file of at most {MAX_ATERM_CONFIG_BYTES} bytes",
                path.display()
            )
        })?;
    parse(&text).map_err(|why| format!("{}: {why}", path.display()))
}

/// Parse a lock's text: `version`, then `[trust]` with `build`, `tree_root`, `compiler_commit`
/// and `receipt`, and `[stock]` with `toolchain`. Comments and blank lines are ignored.
///
/// # Errors
/// Any other table or key, a key given twice, a missing key, a value of the wrong shape, or a
/// `version` other than [`LOCK_VERSION`]: the file is generated, so anything else is a hand edit
/// or a format this reader does not know.
pub fn parse(text: &str) -> Result<TrustLock, String> {
    let mut table = String::new();
    let mut version = None;
    let mut build = None;
    let mut tree_root = None;
    let mut compiler_commit = None;
    let mut receipt = None;
    let mut stock = None;
    for (index, raw) in text.lines().enumerate() {
        let number = index + 1;
        let line = crate::discovery::strip_unquoted_comment(raw).trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with('[') {
            let Some(name) = crate::discovery::table_header(line) else {
                return Err(format!("line {number}: `{line}` is not a table header"));
            };
            if !matches!(name, "trust" | "stock") {
                return Err(format!("line {number}: unknown table `[{name}]`"));
            }
            name.clone_into(&mut table);
            continue;
        }
        let Some((key, rhs)) = line.split_once('=') else {
            return Err(format!("line {number}: `{line}` is not `key = value`"));
        };
        let key = key.trim();
        let rhs = rhs.trim();
        let slot = match (table.as_str(), key) {
            ("", "version") => {
                set(&mut version, number, key, integer(rhs, number, key)?)?;
                continue;
            }
            ("trust", "build") => {
                set(&mut build, number, key, integer(rhs, number, key)?)?;
                continue;
            }
            ("trust", "tree_root") => &mut tree_root,
            ("trust", "compiler_commit") => &mut compiler_commit,
            ("trust", "receipt") => &mut receipt,
            ("stock", "toolchain") => &mut stock,
            ("", key) => return Err(format!("line {number}: unknown key `{key}`")),
            (table, key) => return Err(format!("line {number}: unknown key `{table}.{key}`")),
        };
        let value = crate::discovery::parse_toml_string(rhs)
            .ok_or_else(|| format!("line {number}: `{key}` is not one quoted string"))?;
        set(slot, number, key, value)?;
    }
    match version {
        Some(LOCK_VERSION) => {}
        Some(other) => {
            return Err(format!(
                "version {other}: this reader knows version {LOCK_VERSION} only; a newer aterm \
                 reads it"
            ));
        }
        None => return Err("no `version`".to_string()),
    }
    let missing = |key: &str| format!("no `{key}`");
    let tree_root = tree_root.ok_or_else(|| missing("trust.tree_root"))?;
    if !is_lower_hex(&tree_root, 64) {
        return Err(format!(
            "trust.tree_root `{tree_root}` is not 64 lowercase hex digits"
        ));
    }
    let compiler_commit = compiler_commit.ok_or_else(|| missing("trust.compiler_commit"))?;
    if !is_lower_hex(&compiler_commit, 40) {
        return Err(format!(
            "trust.compiler_commit `{compiler_commit}` is not 40 lowercase hex digits"
        ));
    }
    let receipt = receipt.ok_or_else(|| missing("trust.receipt"))?;
    if receipt.trim().is_empty() {
        return Err("trust.receipt is empty".to_string());
    }
    let stock_toolchain = stock.ok_or_else(|| missing("stock.toolchain"))?;
    if !is_release_number(&stock_toolchain) {
        return Err(format!(
            "stock.toolchain `{stock_toolchain}` is not an exact release (`1.99.1`)"
        ));
    }
    Ok(TrustLock {
        build: build.ok_or_else(|| missing("trust.build"))?,
        tree_root,
        compiler_commit,
        receipt,
        stock_toolchain,
    })
}

fn set<T>(slot: &mut Option<T>, number: usize, key: &str, value: T) -> Result<(), String> {
    if slot.is_some() {
        return Err(format!("line {number}: `{key}` given twice"));
    }
    *slot = Some(value);
    Ok(())
}

fn integer(rhs: &str, number: usize, key: &str) -> Result<u64, String> {
    let digits = rhs.trim();
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!("line {number}: `{key}` is not a whole number"));
    }
    digits
        .parse()
        .map_err(|_| format!("line {number}: `{key}` is out of range"))
}

fn is_lower_hex(text: &str, width: usize) -> bool {
    text.len() == width
        && text
            .bytes()
            .all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

fn is_release_number(text: &str) -> bool {
    let parts: Vec<&str> = text.split('.').collect();
    parts.len() == 3
        && parts
            .iter()
            .all(|p| !p.is_empty() && p.bytes().all(|b| b.is_ascii_digit()))
}

/// The lock's text without its generated head: what a writer puts after its seal line.
#[must_use]
pub fn render_body(lock: &TrustLock) -> String {
    format!(
        "version = {LOCK_VERSION}\n\n[trust]\nbuild = {}\ntree_root = \"{}\"\ncompiler_commit = \
         \"{}\"\nreceipt = \"{}\"\n\n[stock]\ntoolchain = \"{}\"\n",
        lock.build,
        lock.tree_root,
        lock.compiler_commit,
        escape(&lock.receipt),
        lock.stock_toolchain,
    )
}

fn escape(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => out.push_str(&format!("\\u{:04X}", u32::from(ch))),
            ch => out.push(ch),
        }
    }
    out
}

/// `<prefix>/store/trust/<build>`: where the store keeps a build (a link to `<build>.noindex`
/// once laid aside, `crate::layout`).
#[must_use]
pub fn build_dir(prefix: &Path, build: u64) -> PathBuf {
    crate::layout::build_dir(prefix, PROGRAM, build)
}

/// The sidecar `<build><suffix>` beside the store build `dir`, named for the build whether `dir` is
/// its `<build>` or the `<build>.noindex` tree it is laid aside to (what a canonical path reads).
fn beside(dir: &Path, suffix: &str) -> PathBuf {
    let name = dir.file_name().unwrap_or_default();
    let mut name = name
        .to_str()
        .and_then(|n| n.strip_suffix(crate::build_cache::NOINDEX))
        .map_or_else(|| name.to_os_string(), std::ffi::OsString::from);
    name.push(suffix);
    dir.with_file_name(name)
}

/// `<prefix>/store/trust/<build>.tree_root`: the record of the tree root found at a build
/// ([`TREE_ROOT_SUFFIX`]).
#[must_use]
pub fn tree_root_record(prefix: &Path, build: u64) -> PathBuf {
    beside(&build_dir(prefix, build), TREE_ROOT_SUFFIX)
}

/// The identity of the tree at `build_dir` as a record binds it: the device and inode of its
/// physical directory (`<build>.noindex` once laid aside; a rename keeps it, a re-staged tree
/// swapped into place does not). `None` where it cannot be read, or on a platform without inodes.
#[must_use]
pub fn tree_identity(build_dir: &Path) -> Option<String> {
    #[cfg(unix)]
    {
        use std::os::unix::fs::MetadataExt as _;
        let meta = std::fs::metadata(std::fs::canonicalize(build_dir).ok()?).ok()?;
        meta.is_dir()
            .then(|| format!("{}:{}", meta.dev(), meta.ino()))
    }
    #[cfg(not(unix))]
    {
        let _ = build_dir;
        None
    }
}

/// The record's text for tree root `root` of the tree at `build_dir`: a header, the root, and the
/// tree's identity ([`tree_identity`]; `-` where there is none), one per line.
///
/// # Errors
/// When `root` is not 64 lowercase hex digits.
pub fn tree_root_record_text(build_dir: &Path, root: &str) -> Result<String, String> {
    record_text(&identity_or_dash(build_dir), root)
}

/// [`tree_identity`], or `-` where there is none.
#[must_use]
pub fn identity_or_dash(build_dir: &Path) -> String {
    tree_identity(build_dir).unwrap_or_else(|| "-".to_string())
}

fn record_text(identity: &str, root: &str) -> Result<String, String> {
    let root = root.to_ascii_lowercase();
    if !is_lower_hex(&root, 64) {
        return Err(format!("tree root `{root}` is not 64 hex digits"));
    }
    Ok(format!("{TREE_ROOT_HEADER}\n{root}\n{identity}\n"))
}

/// The tree root recorded for the tree at `build_dir` ([`TREE_ROOT_SUFFIX`]), or `None` when
/// there is no record, it does not parse, or it names another tree than the one there now (a
/// build re-staged under the same number since).
#[must_use]
pub fn recorded_root_at(build_dir: &Path) -> Option<String> {
    let text = crate::discovery::read_bounded_text(&beside(build_dir, TREE_ROOT_SUFFIX), 512)?;
    let mut lines = text.lines();
    if lines.next()? != TREE_ROOT_HEADER {
        return None;
    }
    let root = lines.next()?;
    let identity = lines.next()?;
    if lines.next().is_some() || !is_lower_hex(root, 64) {
        return None;
    }
    let here = tree_identity(build_dir).unwrap_or_else(|| "-".to_string());
    (identity == here).then(|| root.to_string())
}

/// The tree root recorded for trust `build` in the store at `prefix` ([`recorded_root_at`]).
#[must_use]
pub fn recorded_tree_root(prefix: &Path, build: u64) -> Option<String> {
    recorded_root_at(&build_dir(prefix, build))
}

/// Record `root` as the tree root of the tree at `build_dir` ([`tree_root_record_text`]):
/// written beside it under a temporary name, then renamed over the record.
///
/// # Errors
/// A malformed `root`, or the write or rename failing.
pub fn write_tree_root_record(build_dir: &Path, root: &str) -> std::io::Result<()> {
    write_tree_root_record_as(build_dir, &identity_or_dash(build_dir), root)
}

/// [`write_tree_root_record`] bound to `identity`, the tree's [`identity_or_dash`] when the root
/// was computed: a fold records the identity it began on, so a tree re-staged while it folded is
/// never described by the old tree's root.
///
/// # Errors
/// As [`write_tree_root_record`].
pub fn write_tree_root_record_as(
    build_dir: &Path,
    identity: &str,
    root: &str,
) -> std::io::Result<()> {
    let text = record_text(identity, root)
        .map_err(|why| std::io::Error::new(std::io::ErrorKind::InvalidInput, why))?;
    let dest = beside(build_dir, TREE_ROOT_SUFFIX);
    let tmp = beside(
        build_dir,
        &format!("{TREE_ROOT_SUFFIX}.tmp-{}", std::process::id()),
    );
    let _ = std::fs::remove_file(&tmp);
    let written = record_options(true)
        .open(&tmp)
        .and_then(|mut file| std::io::Write::write_all(&mut file, text.as_bytes()))
        .and_then(|()| std::fs::rename(&tmp, &dest));
    if written.is_err() {
        let _ = std::fs::remove_file(&tmp);
    }
    written
}

/// How a record beside a store build is created: writable by its owner only, whatever the umask
/// (a store under a system prefix is shared, and another user must not rewrite what a later read
/// believes); `fresh` refuses a file already there.
fn record_options(fresh: bool) -> std::fs::OpenOptions {
    let mut options = std::fs::OpenOptions::new();
    options.write(true);
    if fresh {
        options.create_new(true);
    } else {
        options.create(true).truncate(false);
    }
    #[cfg(unix)]
    std::os::unix::fs::OpenOptionsExt::mode(&mut options, 0o644);
    options
}

/// `<prefix>/store/trust/<build>.locked` ([`LOCKED_SUFFIX`]).
#[must_use]
pub fn locked_mark(prefix: &Path, build: u64) -> PathBuf {
    beside(&build_dir(prefix, build), LOCKED_SUFFIX)
}

/// Mark trust `build` as resolved by a tree's lock now ([`LOCKED_SUFFIX`]), unless a mark from
/// the last hour stands.
///
/// # Errors
/// When the mark cannot be created or its time set.
pub fn mark_locked(prefix: &Path, build: u64) -> std::io::Result<()> {
    mark_used(&build_dir(prefix, build))
}

/// Retain an explicitly installed or resolved store build through the existing keep window.
/// The sidecar is outside its signed payload; it grants no executable or signature authority.
/// Callers hold the store mutation lock or the build's lease while recording the use.
///
/// # Errors
/// When the mark cannot be created or its time set.
pub fn mark_used(build_dir: &Path) -> std::io::Result<()> {
    let mark = beside(build_dir, LOCKED_SUFFIX);
    let now = std::time::SystemTime::now();
    match std::fs::symlink_metadata(&mark) {
        Ok(metadata) => {
            if !metadata.is_file() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    "the build retention mark is not a regular file",
                ));
            }
            if metadata
                .modified()
                .is_ok_and(|at| now.duration_since(at).is_ok_and(|age| age < MARK_FRESH))
            {
                return Ok(());
            }
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
        Err(error) => return Err(error),
    }
    let file = record_options(false).open(&mark)?;
    file.set_modified(now)
}

/// Whether the store build at `build_dir` was explicitly installed or resolved within
/// [`LOCKED_KEEP`] of `now` ([`mark_used`]): gc keeps it.
#[must_use]
pub fn locked_within_keep(build_dir: &Path, now: std::time::SystemTime) -> bool {
    std::fs::symlink_metadata(beside(build_dir, LOCKED_SUFFIX))
        .and_then(|m| m.modified())
        .is_ok_and(|at| now.duration_since(at).map_or(true, |age| age < LOCKED_KEEP))
}

/// The `commit-hash` the `trustc` in `bin` answers to `-vV`, or `None` when it does not answer
/// one within the probe bound.
#[must_use]
pub fn compiler_commit(bin: &Path) -> Option<String> {
    compiler_commit_of(&bin.join(tool_file("trustc")))
}

/// The commit-hash the compiler at `rustc` answers `-vV` with (any rustc-like driver).
#[must_use]
pub fn compiler_commit_of(rustc: &Path) -> Option<String> {
    let text = crate::discovery::bounded_stdout(rustc, &["-vV"], crate::discovery::probe_bound())?;
    commit_hash_line(&text)
}

/// The 40-hex `commit-hash:` of a compiler's `-vV` text.
#[must_use]
pub fn commit_hash_line(text: &str) -> Option<String> {
    text.lines()
        .find_map(|l| l.strip_prefix("commit-hash: "))
        .map(|c| c.trim().to_string())
        .filter(|c| is_lower_hex(c, 40))
}

/// Where the build a lock names stands in an atpkg store.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum LockedBuild {
    /// The store holds it with the lock's tree root: its tools are in `bin`.
    Present {
        /// `<prefix>/store/trust/<build>/bin`.
        bin: PathBuf,
    },
    /// The store holds no complete, runnable build of that number.
    Absent,
    /// The store holds that number with no record of the tree root its install verified.
    Unrecorded,
    /// The store holds that number with another tree.
    Mismatch {
        /// The tree root the store recorded for it.
        recorded: String,
    },
}

/// `<prefix>/store/trust/<build>.ready`: the marker that says trust `build`'s install completed
/// ([`crate::layout::READY_SUFFIX`]).
#[must_use]
pub fn ready_marker(prefix: &Path, build: u64) -> PathBuf {
    beside(&build_dir(prefix, build), crate::layout::READY_SUFFIX)
}

/// Where `lock`'s build stands in the store at `prefix` ([`LockedBuild`]). A build without its
/// [`ready_marker`] is absent: a stage cut short, or one whose resolve check refused it and whose
/// tree a first-exec hold keeps.
#[must_use]
pub fn locked_build(prefix: &Path, lock: &TrustLock) -> LockedBuild {
    let bin = build_dir(prefix, lock.build).join("bin");
    let targo = bin.join(tool_file("targo"));
    let ready =
        std::fs::symlink_metadata(ready_marker(prefix, lock.build)).is_ok_and(|m| m.is_file());
    if !ready || !is_executable_file(&targo) || crate::discovery::is_pending_stub(&targo) {
        return LockedBuild::Absent;
    }
    match recorded_tree_root(prefix, lock.build) {
        None => LockedBuild::Unrecorded,
        Some(recorded) if recorded == lock.tree_root => LockedBuild::Present { bin },
        Some(recorded) => LockedBuild::Mismatch { recorded },
    }
}

impl LockedBuild {
    /// Why a tree cannot compile with the lock's build here, with what to run; `None` when it can.
    /// The act is the build's install, unless the store's signed manifests say no install serves
    /// this target ([`Found::unpublished`]): then `local`, the local build the caller's own
    /// resolution takes in the lock's place ([`LOCAL_SYSROOT_REMEDY`], or
    /// [`LOCAL_SYSROOT_OR_STAGE2_REMEDY`] where it reads `TRUST_STAGE2_BIN` first).
    #[must_use]
    pub fn refusal(&self, found: &Found, lock: &TrustLock, local: &str) -> Option<String> {
        let named = format!(
            "{} names Trust build {} (tree root {})",
            found.path.display(),
            lock.build,
            short(&lock.tree_root)
        );
        let fix = |purpose: &str| match &found.unpublished {
            None => format!(
                "run `aterm pkg install trust --build {}`{purpose}",
                lock.build
            ),
            Some(why) => format!("no published install of it serves this machine ({why}); {local}"),
        };
        match self {
            Self::Present { .. } => None,
            Self::Absent => Some(format!(
                "{named}, which this machine's store does not hold: {}",
                fix("")
            )),
            Self::Unrecorded => Some(format!(
                "{named}; this machine's store holds that build with no record of the tree its \
                 install verified: {}",
                fix(" to verify and record it")
            )),
            Self::Mismatch { recorded } => Some(format!(
                "{named}; this machine's store holds that build number with tree root {}, \
                 another build: {}",
                short(recorded),
                fix(" to replace it")
            )),
        }
    }
}

fn short(root: &str) -> &str {
    root.get(..12).unwrap_or(root)
}

